const provinceIds = new Set(IRAN_PROVINCES_1404.map((item)=>item.id));
const cityProvincePairs = new Set(IRAN_CITIES_1404.map((item)=>item.provinceId+"\0"+item.id));

export function isIranProvinceReference1404(provinceId:string):boolean {
  return provinceIds.has(provinceId);
}
export function isIranProvinceCityPair1404(provinceId:string,cityId:string):boolean {
  return cityProvincePairs.has(provinceId+"\0"+cityId);
}
export function citiesForIranProvince1404(provinceId:string):readonly IranCityReference[] {
  if(!provinceIds.has(provinceId)) return [];
  return IRAN_CITIES_1404.filter((item)=>item.provinceId===provinceId);
}
